    """Utilizes a finite state machine approach to parse JSON strings into Python objects."""

    class JSONParser:
        def __init__(self, input_string):
            self.s = input_string
            self.length = len(input_string)
            self.position = 0
            self.state = 'START'
            self.buffer = ''

        def parse(self):
            result = self.next_token()
            if self.position < self.length:
                raise ValueError("Extra data after parsing")
            return result

        def next_token(self):
            while self.position < self.length:
                char = self.s[self.position]
                if self.state == 'START':
                    if char in ' \n\t\r':
                        self.position += 1
                        continue
                    elif char == '"':
                        self.state = 'STRING'
                        self.buffer = ''
                        self.position += 1
                    elif char == '{':
                        self.position += 1
                        return self.parse_object()
                    elif char == '[':
                        self.position += 1
                        return self.parse_array()
                    elif char == 't':
                        self.position += 4
                        return True
                    elif char == 'f':
                        self.position += 5
                        return False
                    elif char == 'n':
                        self.position += 4
                        return None
                    elif char.isdigit() or char == '-':
                        return self.parse_number()
                    else:
                        raise ValueError(f"Unexpected character: {char}")
                elif self.state == 'STRING':
                    if char == '\\':
                        self.position += 1
                        if self.position < self.length:
                            self.buffer += self.handle_escape(self.s[self.position])
                    elif char == '"':
                        self.state = 'START'
                        self.position += 1
                        return self.buffer
                    else:
                        self.buffer += char
                    self.position += 1

        def handle_escape(self, char):
            escape_chars = {
                '"': '"',
                '\\': '\\',
                '/': '/',
                'b': '\b',
                'f': '\f',
                'n': '\n',
                'r': '\r',
                't': '\t',
            }
            return escape_chars.get(char, char)

        def parse_array(self):
            array = []
            while self.position < self.length:
                char = self.s[self.position]
                if char in ' \n\t\r':
                    self.position += 1
                    continue
                elif char == ']':
                    self.position += 1
                    return array
                else:
                    array.append(self.next_token())
                    char = self.s[self.position]
                    if char == ',':
                        self.position += 1
                    elif char == ']':
                        self.position += 1
                        return array
                    else:
                        raise ValueError("Expected ',' or ']' in array")

        def parse_object(self):
            obj = {}
            while self.position < self.length:
                char = self.s[self.position]
                if char in ' \n\t\r':
                    self.position += 1
                    continue
                elif char == '}':
                    self.position += 1
                    return obj
                else:
                    key = self.next_token()
                    if self.position < self.length and self.s[self.position] == ':':
                        self.position += 1
                        value = self.next_token()
                        obj[key] = value
                    else:
                        raise ValueError("Expected ':' after key in object")

        def parse_number(self):
            start = self.position
            if self.s[start] == '-':
                self.position += 1
            while (self.position < self.length and
