                return self.parse_number()
            elif self.s[self.index:self.index + 4] == 'true':
                self.index += 4
                return True
            elif self.s[self.index:self.index + 5] == 'false':
                self.index += 5
                return False
            elif self.s[self.index:self.index + 4] == 'null':
                self.index += 4
                return None
            else:
                raise ValueError(f"Unexpected character: {char}")

