            self.index += 1  # Skip the opening quote
            result = []
            while self.index < self.length:
                char = self.s[self.index]
                if char == '"':
                    self.index += 1  # Skip the closing quote
                    return ''.join(result)
                elif char == '\\':
                    self.index += 1
                    if self.index < self.length:
                        escape_char = self.s[self.index]
                        if escape_char in '"\\/bfnrt':
                            result.append(self.handle_escape(escape_char))
                        else:
                            raise ValueError(f"Invalid escape character: {escape_char}")
                else:
                    result.append(char)
                self.index += 1
            raise ValueError("Unterminated string")

        def handle_escape(self, char):
            escape_chars = {
                '"': '"',
                '\\': '\\',
                '/': '/',
                'b': '\b',
                'f': '\f',
                'n': '\n',
                'r': '\r',
                't': '\t',
            }
            return escape_chars[char]

        def parse_number(self):
